func:
const nid = v => `ns=3;s=${env.get('ROBOT_ALIAS') || 'robot'}/RAPID/T_ROB1/${env.get('RAPID_MOD') || 'Reto2_Handshake'}/${v}`;
// msg.topic = nombre del tag (ROBOT_START o ROBOT_ESTOP); mismo nombre en RAPID
const tag = msg.topic;
const v = msg.payload === true;
const plc = flow.get('plcAlRobot') || {};
plc[tag] = v;
flow.set('plcAlRobot', plc);
const ts = flow.get('alRobotTs') || {};
ts[tag] = Date.now();
flow.set('alRobotTs', ts);
const b = x => (x ? 1 : 0);
node.status({ fill: plc.ROBOT_ESTOP ? 'red' : plc.ROBOT_START ? 'green' : 'grey', shape: 'dot', text: `→ robot: START ${b(plc.ROBOT_START)} · ESTOP ${b(plc.ROBOT_ESTOP)}` });
return { topic: nid(tag), datatype: 'Boolean', payload: v };

const nid = v => `ns=3;s=${env.get('ROBOT_ALIAS') || 'robot'}/RAPID/T_ROB1/${env.get('RAPID_MOD') || 'Reto2_Handshake'}/${v}`;
// No apilar rondas si el Gateway está lento: espera a que termine la anterior (máx. 3 s)
const r = flow.get('rondaTs');
if (r && Date.now() - r < 3000) return null;
const ronda = Date.now();
flow.set('rondaTs', ronda);
const vars = ['ROBOT_READY', 'ROBOT_START', 'ROBOT_BUSY', 'ROBOT_DONE', 'ROBOT_ESTOP', 'bParoActivo',
  'nEstado', 'nCiclosRobot', 'nMetaCiclos', 'nCiclosLote', 'nCicloActual', 'nVida'];
return [vars.map(v => ({ topic: nid(v), variable: v, ronda, nVars: vars.length }))];

const nid = v => `ns=3;s=${env.get('ROBOT_ALIAS') || 'robot'}/RAPID/T_ROB1/${env.get('RAPID_MOD') || 'Reto2_Handshake'}/${v}`;
const est = flow.get('robot') || {};
est[msg.variable] = msg.payload;
flow.set('robot', est);
// Las lecturas pueden llegar en cualquier orden: la ronda termina al llegar las nVars
if (context.get('ronda') !== msg.ronda) { context.set('ronda', msg.ronda); context.set('n', 0); }
context.set('n', context.get('n') + 1);
if (context.get('n') < msg.nVars) return null;

const now = Date.now();
flow.set('rondaTs', null);
flow.set('robotOkTs', now);
global.set('robot', Object.assign({}, est, { ts: now })); // para el Dashboard (pestaña 06)

// Watchdog de EJECUCIÓN (RAPID v4): nVida avanza cada 0,5 s solo si el programa ejecuta. Si no avanza en 3 s
// (simulación o programa detenido), el READY del robot es un valor viejo: al PLC se le manda READY = 0 y no envía START.
const vida = flow.get('vida') || {};
if (est.nVida !== vida.v) { vida.v = est.nVida; vida.ts = now; }
flow.set('vida', vida);
const ejecutando = now - (vida.ts || 0) < 3000;
if (ejecutando !== flow.get('ejecutando')) {
  global.set('avisoRobot', { texto: ejecutando ? 'Robot ejecutando de nuevo (nVida avanza)' : 'Robot detenido: el programa RAPID no está ejecutando (nVida no avanza); ROBOT_READY = 0 en el PLC', ts: now });
  if (!ejecutando) node.warn('Robot detenido (nVida no avanza): ROBOT_READY = 0 en el PLC');
}
flow.set('ejecutando', ejecutando);
global.set('robotEjecutando', ejecutando);

const env_ = flow.get('enviado') || {};
const resync = now - (flow.get('resyncTs') || 0) > 5000;
if (resync) flow.set('resyncTs', now);
const outs = [null, null, null, null];
['ROBOT_READY', 'ROBOT_BUSY', 'ROBOT_DONE'].forEach((v, i) => {
  const val = est[v] === true && (v !== 'ROBOT_READY' || ejecutando);
  if (resync || env_[v] !== val) { outs[i] = { topic: v, payload: val }; env_[v] = val; }
});
flow.set('enviado', env_);

// START/ESTOP del robot distinto al del PLC (escritura perdida, reinicio del robot...) → reescribir
const plc = flow.get('plcAlRobot') || {};
const ts = flow.get('alRobotTs') || {};
const reesc = [];
for (const tag of ['ROBOT_START', 'ROBOT_ESTOP']) {
  if (typeof plc[tag] === 'boolean' && est[tag] !== plc[tag] && now - (ts[tag] || 0) > 1500) {
    reesc.push({ topic: nid(tag), datatype: 'Boolean', payload: plc[tag] });
    ts[tag] = now;
    node.warn(tag + ' del robot (' + est[tag] + ') ≠ PLC (' + plc[tag] + '): se reescribe');
  }
}
flow.set('alRobotTs', ts);
if (reesc.length) outs[3] = reesc;

const b = v => (v === true ? 1 : v === false ? 0 : '?');
const nombres = ['iniciando', 'READY', 'BUSY', 'DONE', 'bajar START'];
const paso = !ejecutando ? 'DETENIDO (nVida)' : est.bParoActivo ? 'PARO' : (nombres[est.nEstado] ?? est.nEstado);
const fill = !ejecutando ? 'red' : est.bParoActivo ? 'red' : est.ROBOT_BUSY ? 'yellow' : est.ROBOT_DONE ? 'blue' : est.ROBOT_READY ? 'green' : 'grey';
const ciclo = est.ROBOT_BUSY ? ` · ciclo ${est.nCicloActual}/${est.nCiclosLote}` : ` · N=${est.nMetaCiclos}`;
node.status({ fill, shape: 'dot', text: `${paso} · R${b(est.ROBOT_READY)} S${b(est.ROBOT_START)} B${b(est.ROBOT_BUSY)} D${b(est.ROBOT_DONE)} E${b(est.ROBOT_ESTOP)}${ciclo} · rutinas ${est.nCiclosRobot ?? '?'}` });
return outs;

const age = Date.now() - (flow.get('robotOkTs') || 0);
const ok = age < 3000;
const antes = flow.get('robotComOK');
flow.set('robotComOK', ok);
global.set('robotComOK', ok); // para el Dashboard
if (ok) { node.status({ fill: 'green', shape: 'dot', text: 'robot OK' }); return null; }
node.status({ fill: 'red', shape: 'ring', text: 'sin respuesta del robot (' + Math.round(age / 1000) + ' s)' });
if (antes === false) return null; // ya avisado
flow.set('enviado', {}); // al volver, la ronda reescribe todo
node.warn('Comunicación con el robot perdida: ROBOT_READY = 0 en el PLC');
return { topic: 'ROBOT_READY', payload: false };

// La salida 2 del cliente OPC UA trae también avisos de estado con error = null
if (!msg.error) return null;
return msg;

const t = {};
for (const [k, v] of Object.entries(msg.payload)) t[k.replace(/^Program:[^.]+\./, '')] = v;
const activa = l => l.filter(e => t[e]).join('+') || '—';
const g1 = activa([...Array(11).keys()].map(i => 'E' + i));
const g2 = activa(['R0', 'R1', 'R2']);
const g0 = activa(['S0', 'S1', 'S2', 'S3']);
const b = v => (v ? 1 : 0);
flow.set('plc', t);
global.set('plc', t); // para el Dashboard
node.status({ fill: t.ROBOT_START ? 'green' : 'blue', shape: 'dot', text: `G1 ${g1} · G2 ${g2} · G0 ${g0} · CNT ${t.CNT_CAJAS} · START ${b(t.ROBOT_START)} · R${b(t.ROBOT_READY)} B${b(t.ROBOT_BUSY)} D${b(t.ROBOT_DONE)}` });
msg.payload = { G1: g1, G2: g2, G0: g0, CNT_CAJAS: t.CNT_CAJAS, ROBOT_START: t.ROBOT_START, ROBOT_READY: t.ROBOT_READY, ROBOT_BUSY: t.ROBOT_BUSY, ROBOT_DONE: t.ROBOT_DONE, ALM_ROBOT_NO_DISP: t.ALM_ROBOT_NO_DISP };
return msg;

const nid = v => `ns=3;s=${env.get('ROBOT_ALIAS') || 'robot'}/RAPID/T_ROB1/${env.get('RAPID_MOD') || 'Reto2_Handshake'}/${v}`;
const n = Number(msg.payload);
if (!Number.isInteger(n) || n < 1 || n > 5) {
  node.status({ fill: 'red', shape: 'ring', text: 'rechazado: N = ' + msg.payload + ' (1 a 5)' });
  node.warn('nMetaCiclos rechazado: ' + msg.payload + ' (debe ser entero de 1 a 5)');
  global.set('avisoRobot', { texto: 'N rechazado: ' + msg.payload + ' (1 a 5)', ts: Date.now() });
  return null;
}
const est = flow.get('robot') || {};
if (est.ROBOT_BUSY) {
  node.status({ fill: 'yellow', shape: 'ring', text: 'rechazado: robot BUSY' });
  node.warn('nMetaCiclos no se cambia con el robot BUSY');
  global.set('avisoRobot', { texto: 'N no se cambia con el robot BUSY', ts: Date.now() });
  return null;
}
node.status({ fill: 'blue', shape: 'dot', text: 'N = ' + n + ' enviado' });
global.set('avisoRobot', { texto: 'N = ' + n + ' enviado al robot', ts: Date.now() });
return { topic: nid('nMetaCiclos'), datatype: 'Float', payload: n };

const nid = v => `ns=3;s=${env.get('ROBOT_ALIAS') || 'robot'}/RAPID/T_ROB1/${env.get('RAPID_MOD') || 'Reto2_Handshake'}/${v}`;
const est = flow.get('robot') || {};
const aviso = t => global.set('avisoRobot', { texto: t, ts: Date.now() });
if (flow.get('robotComOK') !== true) {
  node.status({ fill: 'red', shape: 'ring', text: 'rechazado: sin comunicación' });
  aviso('Lotes no reiniciados: sin comunicación con el robot');
  return null;
}
if (est.ROBOT_BUSY || est.nEstado !== 1) {
  node.status({ fill: 'yellow', shape: 'ring', text: 'rechazado: robot no está en READY' });
  aviso('Lotes no reiniciados: el robot debe estar en READY');
  return null;
}
node.status({ fill: 'blue', shape: 'dot', text: 'nCiclosRobot = 0 enviado' });
aviso('Lotes atendidos reiniciados a 0');
return { topic: nid('nCiclosRobot'), datatype: 'Float', payload: 0 };

const p = global.get('plc') || {};
const r = global.get('robot') || {};
const hayPlc = Object.keys(p).length > 0;
const b = v => (v ? 1 : 0);
const idx = (pre, n) => { for (let i = 0; i < n; i++) if (p[pre + i]) return i; return -1; };
const al = flow.get('alarmas') || { activa: {}, desde: {}, ack: {}, eventos: [] };
const avs = [global.get('avisoRobot'), global.get('avisoSCADA')].filter(Boolean).sort((a, c) => c.ts - a.ts);
const aviso = avs.length ? new Date(avs[0].ts).toLocaleTimeString('es-CO') + ' · ' + avs[0].texto : '—';
const num = (v, d) => (typeof v === 'number' && !Number.isNaN(v) ? v : d);
// Coherencia PLC ↔ robot para 'Condiciones para operar': falla solo si la diferencia dura > 2 s
// (el puente copia cada cambio en ≤ 0,5 s; sin esta espera el panel parpadearía en cada transición)
const tE = Date.now();
const ambos = hayPlc && global.get('robotComOK') === true;
const sync = (k, iguales) => { if (iguales) { context.set(k, null); return 1; } const t0 = context.get(k); if (!t0) { context.set(k, tE); return 1; } return tE - t0 < 2000 ? 1 : 0; };
const estado = {
  PERM_READY_SYNC: ambos ? sync('difReady', !!p.ROBOT_READY === !!r.ROBOT_READY) : 0,
  PERM_START_SYNC: ambos ? sync('difStart', !!p.ROBOT_START === !!r.ROBOT_START) : 0,
  BTN_STOP_OK: b(p.SN_PP01_HS_02_STOP), BTN_ESTOP_OK: b(p.SN_PP01_HS_03_ESTOP),
  PLC_COM: b(hayPlc && flow.get('plcCom') !== false),
  ROBOT_COM_OK: b(global.get('robotComOK') === true),
  ROBOT_EJEC: b(global.get('robotEjecutando') !== false), // RAPID v4: nVida avanza (sin dato aún = se asume que sí)
  PROC_RUNNING: b(p.PROC_RUNNING), CNT_CAJAS: num(p.CNT_CAJAS, 0), CNT_PRESET: num(p.CNT_PRESET, 5),
  ETAPA_PLANTA: idx('E', 11), ETAPA_LOTE: idx('R', 3), ETAPA_SEG: idx('S', 4),
  BANDA_ENTRADA: b(p.SN_CV_101_01), BANDA_SALIDA: b(p.SN_CV_101_02),
  EJE_X_POS: p.SN_PP01_MTR_X ? 100 : 0, EJE_Z_POS: p.SN_PP01_MTR_Z ? 100 : 0,
  EJE_X_MOV: b(p.SN_PP01_AXIS_X_MOVING), EJE_Z_MOV: b(p.SN_PP01_AXIS_Z_MOVING), PINZA_CERRADA: b(p.SN_PP01_GR01),
  SEN_CAJA_ENTRADA: b(p.SN_CV_101_01_ZS_01), SEN_CAJA_SALIDA: b(p.SN_CV_101_01_ZS_02), SEN_PINZA_CAJA: b(p.SN_PP01_GR01_ZS_01),
  ROBOT_READY: b(r.ROBOT_READY), ROBOT_START: b(p.ROBOT_START), ROBOT_BUSY: b(r.ROBOT_BUSY), ROBOT_DONE: b(r.ROBOT_DONE), ROBOT_ESTOP: b(r.ROBOT_ESTOP),
  nEstado: num(r.nEstado, 0), bParoActivo: b(r.bParoActivo), nCicloActual: num(r.nCicloActual, 0), nCiclosLote: num(r.nCiclosLote, 0),
  nMetaCiclos: num(r.nMetaCiclos, 0), nCiclosRobot: num(r.nCiclosRobot, 0), nPath: num(r.nPath, 0),
  PRE_CAJA_NO_LLEGA: num(p.ALM_PRE_CAJA_NO_LLEGA, ''), PRE_CAJA_PERDIDA: num(p.ALM_PRE_CAJA_PERDIDA, ''), PRE_ROBOT_NO_DISP: num(p.ALM_PRE_ROBOT_NO_DISP, ''),
  PRE_PINZA_VACIA: num(p.ALM_PRE_PINZA_VACIA, ''),
  T_MAX_CICLO: flow.get('tMaxCiclo') || 30,
  ULTIMO_AVISO: aviso,
  ALM_DESDE: al.desde, ALM_ACK: al.ack, EVENTOS: al.eventos.slice(0, 30),
};
for (const t of ['ALM_EMERGENCIA', 'ROBOT_COM', 'ALM_CAJA_PERDIDA', 'ALM_PINZA_VACIA', 'ALM_ROBOT_NO_DISP', 'ROBOT_TIEMPO', 'ROBOT_SIN_ARRANQUE', 'ROBOT_DETENIDO', 'ALM_CAJA_NO_LLEGA']) estado[t] = b(al.activa[t]);
const key = JSON.stringify(estado);
const now = Date.now();
if (key === context.get('key') && now - (context.get('ts') || 0) < 5000) return null;
context.set('key', key); context.set('ts', now);
return { topic: 'estado', payload: estado };

// eth-ip: online = verde; connecting = amarillo; offline / error = rojo
const ok = msg.status && msg.status.fill === 'green';
flow.set('plcCom', ok);
global.set('plcCom', ok); // la capa de nivel 3 (pestaña 07) también lo usa
node.status({ fill: ok ? 'green' : 'red', shape: 'dot', text: ok ? 'PLC OK' : 'PLC: ' + (msg.status && msg.status.text) });
return null;

// ===== scada_logica.js (incrustado por gen06_Dashboard.js; no editar aquí) =====
// Lógica pura del SCADA (pestaña 06). Sin dependencias: gen06_Dashboard.js la incrusta en los function nodes.
// Pruebas: node --test node-red/propuestas/scada/test/

// ---------- Alarma del robot: "Robot no ejecuta la orden" (ROBOT_SIN_ARRANQUE) ----------
// El robot tiene START (lo ve en su PERS) y no está ni BUSY ni DONE por más de 10 s. Casos reales:
//  · simulación de RobotStudio detenida: el Gateway sigue entregando los últimos valores (p. ej. READY = 1);
//  · programa RAPID reiniciado desde main con START = 1 ya activo: queda en nEstado 4 ("bajar START", READY = 0)
//    mientras el PLC mantiene START esperando DONE → bloqueo del handshake.
// Con DONE = 1 no es falla: el robot terminó y espera que el PLC baje START.
const SIN_ARRANQUE_MS = 10000;
function evaluarSinArranque(st = {}, { robot = {}, comOK }, now) {
  const cond = comOK === true && robot.ROBOT_START === true && robot.ROBOT_BUSY !== true && robot.ROBOT_DONE !== true;
  const desde = cond ? (st.desde ?? now) : null;
  return { st: { ...st, desde }, activa: cond && now - desde > SIN_ARRANQUE_MS };
}

// Causa legible de que el robot tenga START y no la ejecute (según nEstado)
function causaSinArranque(robot = {}) {
  if (robot.nEstado === 4) return 'el robot espera que START baje: el programa RAPID se reinició con una orden pendiente (bloqueo del handshake; START no baja hasta DONE)';
  return 'el robot recibió START y no arrancó (¿simulación de RobotStudio o programa RAPID detenido?)';
}

// ---------- RESET CONTADOR: por qué no puede actuar (null = sí puede) ----------
// El Ladder solo reinicia CNT_CAJAS con G2 en R0 (sin orden al robot): XIC(SCADA_RESET_CNT) XIC(R0) MOV(0, CNT_CAJAS)
function motivoNoResetCnt({ plc = {}, robot = {}, plcCom }) {
  if (plcCom === false) return 'sin comunicación con el PLC';
  if (plc.PROC_RUNNING) return 'la planta está en marcha: deténgala con STOP primero';
  if (plc.R1) {
    if (robot.ROBOT_START && !robot.ROBOT_BUSY && !robot.ROBOT_DONE) return causaSinArranque(robot) + '; el contador se reinicia solo cuando el robot termine';
    return 'hay una orden al robot en curso (lote completo, G2 en R1): el contador se reinicia solo cuando el robot termine';
  }
  if (plc.R2) return 'el lote se está cerrando (G2 en R2): espere un instante';
  if (!plc.R0) return 'el GRAFCET del lote (G2) no está en reposo (R0)';
  return null;
}


// ===== fin de scada_logica.js =====
// Salidas: 1 START · 2 STOP · 3 RESET · 4 RESET CONTADOR · 5 ACK (PLC) · 6 ACK (alarmas del robot)
//          7 N → 05 · 8 reiniciar lotes → 05 · 9 presets PLC · 10 tiempo máx. robot · 11 consulta · 12 cajas por lote
//          13 capa de nivel 3 → 07 (todo topic 'mes_*': turnos, PRI, tendencias, registros)
const outs = new Array(13).fill(null);
if (typeof msg.topic === 'string' && msg.topic.startsWith('mes_')) {
  outs[12] = { topic: msg.topic, payload: msg.payload, ventana: msg.ventana, tipo: msg.tipo, desde: msg.desde, hasta: msg.hasta };
  node.status({ fill: 'blue', shape: 'dot', text: msg.topic + ' ' + (msg.payload ?? '') });
  return outs;
}
const cmd = { CMD_START: 0, CMD_STOP: 1, CMD_RESET: 2, CMD_RESET_CONTADOR: 3, CMD_REINICIAR_LOTES: 7 };
const pre = { PRE_CAJA_NO_LLEGA: 'ALM_PRE_CAJA_NO_LLEGA', PRE_CAJA_PERDIDA: 'ALM_PRE_CAJA_PERDIDA', PRE_ROBOT_NO_DISP: 'ALM_PRE_ROBOT_NO_DISP', PRE_PINZA_VACIA: 'ALM_PRE_PINZA_VACIA' };
if (msg.topic === 'cmd' && msg.payload === 'CMD_RESET_CONTADOR') {
  // El Ladder solo reinicia CNT_CAJAS con G2 en R0: si no se puede, se explica la causa (decisión de Juan) y no se envía el pulso
  const p = global.get('plc') || {};
  const motivo = motivoNoResetCnt({ plc: p, robot: global.get('robot') || {}, plcCom: global.get('plcCom') !== false && Object.keys(p).length > 0 });
  if (motivo) {
    global.set('avisoSCADA', { texto: 'No se pudo reiniciar el contador: ' + motivo, ts: Date.now() });
    node.status({ fill: 'red', shape: 'ring', text: 'RESET CNT rechazado' });
    return null;
  }
  // Confirmación: 1,5 s después del pulso se verifica que el PLC lo haya aplicado
  setTimeout(() => {
    const q = global.get('plc') || {};
    global.set('avisoSCADA', { texto: q.CNT_CAJAS === 0 ? 'Contador de cajas reiniciado' : 'No se pudo reiniciar el contador: el PLC no lo aplicó (' + (motivoNoResetCnt({ plc: q, robot: global.get('robot') || {}, plcCom: true }) || 'causa no identificada') + ')', ts: Date.now() });
  }, 1500);
}
if (msg.topic === 'cmd') {
  if (msg.payload === 'CMD_ACK_ALARMAS') { outs[4] = { payload: true }; outs[5] = { topic: 'ack' }; }
  else if (msg.payload in cmd) outs[cmd[msg.payload]] = { payload: true };
  else { node.warn('Comando desconocido: ' + msg.payload); return null; }
} else if (msg.topic === 'N') outs[6] = { payload: msg.payload };
else if (msg.topic === 'cfg' && msg.tag in pre) outs[8] = { topic: pre[msg.tag], payload: msg.payload };
else if (msg.topic === 'cfg' && msg.tag === 'T_MAX_CICLO') outs[9] = { topic: 'tMax', payload: msg.payload };
else if (msg.topic === 'consulta') outs[10] = { topic: 'consulta', desde: msg.desde, hasta: msg.hasta };
else if (msg.topic === 'cfg' && msg.tag === 'CNT_PRESET') outs[11] = { payload: msg.payload };
else return null;
node.status({ fill: 'blue', shape: 'dot', text: msg.topic + ' ' + (msg.tag || '') + ' ' + msg.payload });
return outs;

// CNT_PRESET solo se compara en el Ladder (T1, T2, T10, T11, TR1): basta con escribirlo.
// Regla: 1..10, sin orden al robot (G2 en R0) y mayor que las cajas ya contadas. Si se subiera en E10
// con el robot trabajando, T11 (CNT < PRESET) haría arrancar la planta y R2 borraría cajas del conteo.
const p = global.get('plc') || {};
const aviso = t => global.set('avisoSCADA', { texto: t, ts: Date.now() });
const v = Number(msg.payload);
const rechazo = t => { aviso('Cajas por lote rechazado: ' + t); node.status({ fill: 'red', shape: 'ring', text: t }); return null; };
if (!Number.isInteger(v) || v < 1 || v > 10) return rechazo(msg.payload + ' (entero de 1 a 10)');
if (!p.R0) return rechazo('hay una orden al robot en curso (G2 fuera de R0)');
if (v <= (p.CNT_CAJAS || 0)) return rechazo('debe ser mayor que las cajas ya contadas (' + p.CNT_CAJAS + ')');
aviso('Cajas por lote = ' + v + ' enviado al PLC');
node.status({ fill: 'blue', shape: 'dot', text: 'CNT_PRESET = ' + v });
return { payload: v };

const lim = { ALM_PRE_CAJA_NO_LLEGA: [1000, 120000], ALM_PRE_CAJA_PERDIDA: [50, 5000], ALM_PRE_ROBOT_NO_DISP: [1000, 120000], ALM_PRE_PINZA_VACIA: [500, 30000] };
const orden = ['ALM_PRE_CAJA_NO_LLEGA', 'ALM_PRE_CAJA_PERDIDA', 'ALM_PRE_ROBOT_NO_DISP', 'ALM_PRE_PINZA_VACIA'];
const [min, max] = lim[msg.topic] || [];
const v = Number(msg.payload);
if (min === undefined || !Number.isInteger(v) || v < min || v > max) {
  global.set('avisoSCADA', { texto: msg.topic + ' rechazado: ' + msg.payload + ' (entero de ' + min + ' a ' + max + ' ms)', ts: Date.now() });
  node.status({ fill: 'red', shape: 'ring', text: 'rechazado ' + msg.topic });
  return null;
}
global.set('avisoSCADA', { texto: msg.topic + ' = ' + v + ' ms enviado al PLC', ts: Date.now() });
node.status({ fill: 'blue', shape: 'dot', text: msg.topic + ' = ' + v });
const outs = [null, null, null, null];
outs[orden.indexOf(msg.topic)] = { payload: v };
return outs;

// ===== scada_logica.js (incrustado por gen06_Dashboard.js; no editar aquí) =====
