// ---------- Alarma del robot: "Robot no ejecuta la orden" (ROBOT_SIN_ARRANQUE) ----------
// El robot tiene START (lo ve en su PERS) y no está ni BUSY ni DONE por más de 10 s. Casos reales:
//  · simulación de RobotStudio detenida: el Gateway sigue entregando los últimos valores (p. ej. READY = 1);
//  · programa RAPID reiniciado desde main con START = 1 ya activo: queda en nEstado 4 ("bajar START", READY = 0)
//    mientras el PLC mantiene START esperando DONE → bloqueo del handshake.
// Con DONE = 1 no es falla: el robot terminó y espera que el PLC baje START.
const SIN_ARRANQUE_MS = 10000;
function evaluarSinArranque(st = {}, { robot = {}, comOK }, now) {
  const cond = comOK === true && robot.ROBOT_START === true && robot.ROBOT_BUSY !== true && robot.ROBOT_DONE !== true;
  const desde = cond ? (st.desde ?? now) : null;
  return { st: { ...st, desde }, activa: cond && now - desde > SIN_ARRANQUE_MS };
}

// Causa legible de que el robot tenga START y no la ejecute (según nEstado)
function causaSinArranque(robot = {}) {
  if (robot.nEstado === 4) return 'el robot espera que START baje: el programa RAPID se reinició con una orden pendiente (bloqueo del handshake; START no baja hasta DONE)';
  return 'el robot recibió START y no arrancó (¿simulación de RobotStudio o programa RAPID detenido?)';
}

// ---------- RESET CONTADOR: por qué no puede actuar (null = sí puede) ----------
// El Ladder solo reinicia CNT_CAJAS con G2 en R0 (sin orden al robot): XIC(SCADA_RESET_CNT) XIC(R0) MOV(0, CNT_CAJAS)
function motivoNoResetCnt({ plc = {}, robot = {}, plcCom }) {
  if (plcCom === false) return 'sin comunicación con el PLC';
  if (plc.PROC_RUNNING) return 'la planta está en marcha: deténgala con STOP primero';
  if (plc.R1) {
    if (robot.ROBOT_START && !robot.ROBOT_BUSY && !robot.ROBOT_DONE) return causaSinArranque(robot) + '; el contador se reinicia solo cuando el robot termine';
    return 'hay una orden al robot en curso (lote completo, G2 en R1): el contador se reinicia solo cuando el robot termine';
  }
  if (plc.R2) return 'el lote se está cerrando (G2 en R2): espere un instante';
  if (!plc.R0) return 'el GRAFCET del lote (G2) no está en reposo (R0)';
  return null;
}


