// ===== mes_logica.js (incrustado por gen07_MES.js; no editar aquí) =====
// Lógica pura de la capa de Producción y KPIs (nivel 3, ISO 22400) del Reto 2.
// Sin dependencias ni require: gen07_MES.js incrusta este archivo en los function nodes de Node-RED.
// Spec: docs/superpowers/specs/2026-11-11-mes-produccion-kpis-design.md

// ---------- Clasificación de estados (spec 5.3) ----------
const CATEGORIAS = ['SIN_COM', 'EMERGENCIA', 'PLC_SIN_EJECUTAR', 'PARADA_ALARMA', 'FALTA_CAJA', 'BLOQUEO_ROBOT', 'DETENIDA', 'PRODUCIENDO'];
const ETIQUETA = {
  SIN_COM: 'Sin comunicación', EMERGENCIA: 'Emergencia', PLC_SIN_EJECUTAR: 'PLC sin ejecutar',
  PARADA_ALARMA: 'Parada por alarma', FALTA_CAJA: 'Falta de caja', BLOQUEO_ROBOT: 'Bloqueo por robot',
  DETENIDA: 'Detenida por operador', PRODUCIENDO: 'Produciendo', SIN_DATOS: 'Sin datos',
};
const ELEMENTO_ISO = {
  PRODUCIENDO: 'APT', FALTA_CAJA: 'ADET', BLOQUEO_ROBOT: 'ADET', DETENIDA: 'ADET',
  SIN_COM: 'ADOT', EMERGENCIA: 'ADOT', PLC_SIN_EJECUTAR: 'ADOT', PARADA_ALARMA: 'ADOT', SIN_DATOS: 'ADOT',
};
const ALARMAS_DE_PARADA = ['ALM_PINZA_VACIA', 'ALM_CAJA_PERDIDA'];

// Índice de la etapa activa de un GRAFCET (prefijo 'E', 'R' o 'S'), o -1 si ninguna
function etapa(plc, prefijo, n) {
  for (let i = 0; i < n; i++) if (plc && plc[prefijo + i]) return i;
  return -1;
}

// Una categoría por instante, la primera que cumpla en el orden de la spec 5.3
function clasificar({ plc = {}, robot = {}, plcCom }, mem = {}) {
  const g1 = etapa(plc, 'E', 11);
  const g0 = etapa(plc, 'S', 4);
  const etapaAlarma = { ...(mem.etapaAlarma || {}) };
  // Etapa de G1 en el flanco de subida de cada alarma de parada; se borra cuando la alarma baja
  for (const tag of ALARMAS_DE_PARADA) {
    if (!plc[tag]) etapaAlarma[tag] = null;
    else if (etapaAlarma[tag] === null || etapaAlarma[tag] === undefined) etapaAlarma[tag] = g1;
  }
  const res = (categoria, causa) => ({ categoria, causa, mem: { ...mem, etapaAlarma } });

  if (plcCom === false) return res('SIN_COM', 'PLC_COM');
  if (plc.S2 || plc.S3) return res('EMERGENCIA', 'EMERGENCIA');
  if (g1 < 0 && g0 < 0) return res('PLC_SIN_EJECUTAR', 'PLC_PROGRAM');
  for (const tag of ALARMAS_DE_PARADA) {
    // Trabada: la alarma sigue activa y G1 no se movió de la etapa en que apareció
    if (plc[tag] && g1 >= 0 && etapaAlarma[tag] === g1) return res('PARADA_ALARMA', tag);
  }
  if (plc.ALM_CAJA_NO_LLEGA) return res('FALTA_CAJA', 'ALM_CAJA_NO_LLEGA');
  if (g1 === 10) return res('BLOQUEO_ROBOT', robot.ROBOT_BUSY ? 'ROBOT_BUSY' : robot.ROBOT_DONE ? 'DONE' : 'ROBOT_NO_READY');
  if (g1 === 0) return res('DETENIDA', 'E0');
  if (g1 >= 1) return res('PRODUCIENDO', '');
  return res('PLC_SIN_EJECUTAR', 'SIN_ETAPA_G1'); // G0 activo pero G1 vacío fuera de emergencia
}

// ---------- Cajas (spec 5.4) ----------
// prev / ahora = { cnt: CNT_CAJAS, almPerdida: ALM_CAJA_PERDIDA, almPinza: ALM_PINZA_VACIA }. prev = null: base.
// Cajas malas (decisión de Juan): 'perdida' = la pinza la soltó en el traslado; 'no_recogida' = el brazo bajó y no
// tomó caja (pinza vacía), p. ej. porque la caja se salió de la posición de recogida. Una por flanco de subida.
function detectarCajas(prev, ahora) {
  if (!prev) return { buenas: 0, perdidas: 0, noRecogidas: 0, base: true };
  const d = (ahora.cnt || 0) - (prev.cnt || 0);
  return {
    buenas: d > 0 ? d : 0, // los reinicios a 0 (fin de lote, RESET CNT) no cuentan
    perdidas: !prev.almPerdida && ahora.almPerdida ? 1 : 0,
    noRecogidas: !prev.almPinza && ahora.almPinza ? 1 : 0,
    base: false,
  };
}

// ---------- Lotes (spec 5.5) ----------
// Un evento por llamada: 'inicio' (↑E1 sin lote abierto), 'fin_planta' (↑E10), 'inicio_robot' (↑BUSY), 'fin' (↑DONE)
function transicionLote(mem = {}, { plc = {}, robot = {} }, ts) {
  const prev = mem.prev || {};
  const act = { E1: !!plc.E1, E10: !!plc.E10, BUSY: !!robot.ROBOT_BUSY, DONE: !!robot.ROBOT_DONE };
  let abierto = !!mem.abierto;
  let evento = null;
  if (!abierto && act.E1 && !prev.E1) { abierto = true; evento = 'inicio'; }
  else if (abierto && act.E10 && !prev.E10) evento = 'fin_planta';
  else if (abierto && act.BUSY && !prev.BUSY) evento = 'inicio_robot';
  else if (abierto && act.DONE && !prev.DONE) { abierto = false; evento = 'fin'; }
  return { mem: { ...mem, abierto, prev: act, ts }, evento };
}

// ---------- KPIs del turno (spec 5.3–5.5; OEE según ISO 22400) ----------
const div = (a, b) => (b > 0 ? a / b : null);
const media = arr => (arr.length ? arr.reduce((s, x) => s + x, 0) / arr.length : null);

// Segundos de [a, b] (ms) recortados a [ini, fin] (ms)
const recorte = (a, b, ini, fin) => Math.max(0, Math.min(b, fin) - Math.max(a, ini)) / 1000;

// Tiempo real entre dos cajas buenas, solo si todo el intervalo estuvo en PRODUCIENDO (si no, null)
function cicloCaja(tsAnterior, ts, estados) {
  if (tsAnterior === null || tsAnterior === undefined || !(ts > tsAnterior)) return null;
  let prod = 0;
  for (const e of estados || []) {
    if (e.categoria !== 'PRODUCIENDO') continue;
    prod += recorte(e.inicio_ts, e.fin_ts ?? ts, tsAnterior, ts);
  }
  const span = (ts - tsAnterior) / 1000;
  return Math.abs(prod - span) < 0.001 ? span : null;
}

// turno = {inicio_ts, fin_ts|null, pri_s}; estados = [{inicio_ts, fin_ts|null, categoria, causa}];
// cajas = [{ts, tipo:'buena'|'perdida', ciclo_s}]; lotes = [{inicio_ts, fin_planta_ts, inicio_robot_ts, fin_ts, cajas, n_ciclos}]
function kpisTurno({ turno, estados = [], cajas = [], lotes = [], ahora }) {
  const ini = turno.inicio_ts;
  const fin = turno.fin_ts ?? ahora;
  const pbt_s = Math.max(0, (fin - ini) / 1000);

  const t = {};
  for (const c of CATEGORIAS) t[c] = 0;
  let cubierto = 0;
  for (const e of estados) {
    const d = recorte(e.inicio_ts, e.fin_ts ?? ahora, ini, fin);
    t[e.categoria] = (t[e.categoria] || 0) + d;
    cubierto += d;
  }
  const apt_s = t.PRODUCIENDO;
  const perdidas = {};
  for (const c of CATEGORIAS) if (c !== 'PRODUCIENDO') perdidas[c] = t[c];
  perdidas.SIN_DATOS = Math.max(0, pbt_s - cubierto);

  const enTurno = cajas.filter(c => c.ts >= ini && c.ts <= fin);
  const buenas = enTurno.filter(c => c.tipo === 'buena');
  const gq = buenas.length;
  const sq_traslado = enTurno.filter(c => c.tipo === 'perdida').length;
  const sq_recogida = enTurno.filter(c => c.tipo === 'no_recogida').length;
  const sq = sq_traslado + sq_recogida;
  const pq = gq + sq;

  const A = div(apt_s, pbt_s);
  const E = apt_s > 0 && pq > 0 ? div(turno.pri_s * pq, apt_s) : null;
  const Q = div(gq, pq);
  const OEE = A !== null && E !== null && Q !== null ? A * E * Q : null;

  const conCiclo = buenas.filter(c => typeof c.ciclo_s === 'number').sort((a, b) => a.ts - b.ts);
  const horas = pbt_s / 3600;
  const cerrados = lotes.filter(l => l.fin_ts);

  const busy = lotes.filter(l => l.inicio_robot_ts).map(l => recorte(l.inicio_robot_ts, l.fin_ts ?? ahora, ini, fin));
  const rutinas = cerrados.filter(l => l.inicio_robot_ts);

  return {
    pbt_s, apt_s, A, E, Q, OEE, perdidas, gq, sq, pq, sq_traslado, sq_recogida,
    throughput_h: div(gq, horas),
    lotes_h: div(cerrados.length, horas),
    ciclo_medio_s: media(conCiclo.map(c => c.ciclo_s)),
    ciclo_ultimo_s: conCiclo.length ? conCiclo[conCiclo.length - 1].ciclo_s : null,
    robot: {
      utilizacion: div(busy.reduce((s, x) => s + x, 0), pbt_s),
      rutina_media_s: media(rutinas.map(l => (l.fin_ts - l.inicio_robot_ts) / 1000)),
      rutina_ciclo_s: media(rutinas.filter(l => l.n_ciclos > 0).map(l => (l.fin_ts - l.inicio_robot_ts) / 1000 / l.n_ciclos)),
      lotes: cerrados.length,
    },
  };
}

// ---------- KPIs de alarmas (spec 5.6; ISA-18.2 / EEMUA 191; sin avalanchas por decisión de Juan) ----------
const PRIORIDAD = {
  ALM_EMERGENCIA: 'alta', ROBOT_COM: 'alta', ROBOT_DETENIDO: 'alta',
  ALM_CAJA_PERDIDA: 'media', ALM_PINZA_VACIA: 'media', ALM_ROBOT_NO_DISP: 'media', ROBOT_TIEMPO: 'media', ROBOT_SIN_ARRANQUE: 'media',
  ALM_CAJA_NO_LLEGA: 'baja',
};
const CHATTER_N = 3, CHATTER_MS = 60000, VENTANA_10MIN = 600000;

// Alarmas activas según su último evento (activa si no terminó en Normalización); desde = su última Aparición
function alarmasActivas(eventos) {
  const ult = {}, desde = {};
  for (const e of [...(eventos || [])].sort((a, b) => a.ts - b.ts)) {
    ult[e.alarma] = e.evento;
    if (e.evento === 'Aparición') desde[e.alarma] = e.ts;
  }
  const act = {};
  for (const tag in ult) if (ult[tag] !== 'Normalización' && desde[tag] !== undefined) act[tag] = desde[tag];
  return act;
}

// eventos = [{ts, evento: 'Aparición'|'Reconocimiento'|'Normalización', alarma}] · activas = {tag: desde_ts}
function kpisAlarmas({ eventos = [], turno, ahora, activas = {}, umbralEnPieMin = 30 }) {
  const ini = turno.inicio_ts, fin = turno.fin_ts ?? ahora;
  const enTurno = eventos.filter(e => e.ts >= ini && e.ts <= fin).sort((a, b) => a.ts - b.ts);
  const apar = enTurno.filter(e => e.evento === 'Aparición');
  const total = apar.length;
  const horas = (fin - ini) / 3600000;
  const r1 = x => Math.round(x * 10) / 10;

  // Máximo de apariciones en cualquier ventana de 10 min (ventana deslizante)
  let max10 = 0;
  for (let i = 0, j = 0; i < apar.length; i++) {
    while (apar[i].ts - apar[j].ts >= VENTANA_10MIN) j++;
    max10 = Math.max(max10, i - j + 1);
  }

  const cuenta = {};
  for (const e of apar) cuenta[e.alarma] = (cuenta[e.alarma] || 0) + 1;
  let acum = 0;
  const pareto = Object.entries(cuenta).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([tag, n]) => { acum += n; return { tag, n, pct: r1(100 * n / total), acum: r1(100 * acum / total) }; });

  const chattering = Object.keys(cuenta).filter(tag => {
    const ts = apar.filter(e => e.alarma === tag).map(e => e.ts);
    return ts.some((t, i) => i + CHATTER_N - 1 < ts.length && ts[i + CHATTER_N - 1] - t <= CHATTER_MS);
  }).sort();

  const en_pie = Object.entries(activas).map(([tag, desde]) => ({ tag, min: Math.round((ahora - desde) / 60000) }))
    .filter(a => a.min > umbralEnPieMin).sort((a, b) => b.min - a.min);

  // Tiempo de reconocimiento: cada Reconocimiento con la Aparición anterior más reciente (sin pareja) de esa alarma
  const pendiente = {}, tiempos = [];
  for (const e of enTurno) {
    if (e.evento === 'Aparición') (pendiente[e.alarma] = pendiente[e.alarma] || []).push(e.ts);
    else if (e.evento === 'Reconocimiento' && pendiente[e.alarma] && pendiente[e.alarma].length) tiempos.push((e.ts - pendiente[e.alarma].pop()) / 1000);
  }

  const vacia = () => ({ alta: 0, media: 0, baja: 0 });
  const configurada = vacia(), ocurrida = vacia();
  for (const tag in PRIORIDAD) configurada[PRIORIDAD[tag]]++;
  for (const e of apar) if (PRIORIDAD[e.alarma]) ocurrida[PRIORIDAD[e.alarma]]++;

  return {
    total,
    tasa_h: horas > 0 ? r1(total / horas) : null,
    max_10min: max10,
    pareto,
    top10_pct: total ? r1(100 * pareto.slice(0, 10).reduce((s, p) => s + p.n, 0) / total) : null,
    chattering,
    en_pie,
    t_reconocimiento_s: tiempos.length ? r1(media(tiempos)) : null,
    prioridades: { configurada, ocurrida },
  };
}

// ---------- Comandos de la pantalla (spec 5.2, 5.4) ----------
const PRI_MIN = 3, PRI_MAX = 60;
function validarComando(turnoAbierto, { topic, payload }) {
  const no = aviso => ({ ok: false, aviso });
  if (topic === 'mes_cmd') {
    if (payload === 'ABRIR_TURNO') return turnoAbierto ? no('Ya hay un turno abierto: ciérrelo antes de abrir otro') : { ok: true, aviso: 'Turno abierto' };
    if (payload === 'CERRAR_TURNO') return turnoAbierto ? { ok: true, aviso: 'Turno cerrado' } : no('No hay un turno abierto para cerrar');
    return no('Comando de turno desconocido: ' + payload);
  }
  if (topic === 'mes_pri') {
    const v = Number(payload);
    if (turnoAbierto) return no('El PRI solo se cambia con el turno cerrado (el turno conserva su PRI)');
    if (!(v >= PRI_MIN && v <= PRI_MAX)) return no(`PRI rechazado: ${payload} s (de ${PRI_MIN} a ${PRI_MAX} s)`);
    return { ok: true, aviso: `PRI = ${v} s` };
  }
  if (topic === 'mes_enpie') {
    const v = Number(payload);
    if (!(Number.isInteger(v) && v >= 5 && v <= 1440)) return no(`Umbral de alarmas en pie rechazado: ${payload} min (entero de 5 a 1440)`);
    return { ok: true, aviso: `Umbral de alarmas en pie = ${v} min` };
  }
  if (topic === 'mes_trend') return VENTANAS[payload] !== undefined ? { ok: true, aviso: '' } : no('Ventana desconocida: ' + payload);
  if (topic === 'mes_reg') return REGISTROS.includes(payload) ? { ok: true, aviso: '' } : no('Registro desconocido: ' + payload);
  return no('Comando desconocido: ' + topic);
}

// ---------- Tendencias por ventana (Tarea 8) ----------
const VENTANAS = { '15m': 900000, '1h': 3600000, '8h': 8 * 3600000, turno: null };
// 'turno' = el turno abierto (hasta ahora) o el último cerrado (hasta su fin); null sin turno o ventana desconocida
function rangoVentana(ventana, ahora, turno) {
  if (!(ventana in VENTANAS)) return null;
  if (ventana === 'turno') return turno ? { desde_ts: turno.inicio_ts, hasta_ts: turno.fin_ts ?? ahora } : null;
  return { desde_ts: ahora - VENTANAS[ventana], hasta_ts: ahora };
}

// ---------- Registros y CSV (Tarea 9) ----------
const REGISTROS = ['turnos', 'lotes', 'paradas'];
const r1n = x => (x === null || x === undefined ? null : Math.round(x * 10) / 10);
const pct1 = x => (x === null || x === undefined ? null : Math.round(x * 1000) / 10);
const seg = (a, b) => (a !== null && a !== undefined && b !== null && b !== undefined ? r1n((b - a) / 1000) : null);

// datos: filas de mes.db (con 'turno' = nombre en lotes y estados); fmt: ts -> texto de fecha y hora
function tablaRegistro(tipo, datos, ahora, fmt) {
  if (tipo === 'paradas') {
    return {
      columnas: ['Turno', 'Inicio', 'Fin', 'Duración (s)', 'Categoría', 'Elemento ISO', 'Causa'],
      filas: (datos.estados || []).map(e => [e.turno, fmt(e.inicio_ts), e.fin_ts ? fmt(e.fin_ts) : '', seg(e.inicio_ts, e.fin_ts ?? ahora),
        ETIQUETA[e.categoria] || e.categoria, ELEMENTO_ISO[e.categoria] || '', e.causa || '']),
    };
  }
  if (tipo === 'lotes') {
    return {
      columnas: ['Turno', 'Inicio', 'Cajas', 'N ciclos', 'Planta (s)', 'Espera robot (s)', 'Rutina (s)', 'Estado'],
      filas: (datos.lotes || []).map(l => [l.turno, fmt(l.inicio_ts), l.cajas ?? null, l.n_ciclos ?? null,
        seg(l.inicio_ts, l.fin_planta_ts), seg(l.fin_planta_ts, l.inicio_robot_ts), seg(l.inicio_robot_ts, l.fin_ts), l.fin_ts ? 'completo' : 'incompleto']),
    };
  }
  if (tipo === 'turnos') {
    const de = (arr, id) => (arr || []).filter(x => x.turno_id === id);
    return {
      columnas: ['Turno', 'Inicio', 'Fin', 'Duración (s)', 'PRI (s)', 'OEE (%)', 'A (%)', 'E (%)', 'Q (%)', 'Cajas buenas', 'Cajas malas', 'Lotes', 'Cajas/h'],
      filas: (datos.turnos || []).map(t => {
        const k = kpisTurno({ turno: t, estados: de(datos.estados, t.id), cajas: de(datos.cajas, t.id), lotes: de(datos.lotes, t.id), ahora });
        return [t.nombre, fmt(t.inicio_ts), t.fin_ts ? fmt(t.fin_ts) : 'abierto', r1n(k.pbt_s), t.pri_s,
          pct1(k.OEE), pct1(k.A), pct1(k.E), pct1(k.Q), k.gq, k.sq, k.robot.lotes, r1n(k.throughput_h)];
      }),
    };
  }
  return null;
}

// CSV para Excel en español: BOM UTF-8, separador ';', decimales con coma, CRLF
function aCSV(columnas, filas) {
  const celda = v => {
    if (v === null || v === undefined) return '';
    if (typeof v === 'number') return String(v).replace('.', ',');
    const s = String(v);
    return /[;"\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  return '﻿' + [columnas, ...filas].map(f => f.map(celda).join(';')).join('\r\n') + '\r\n';
}


